// JAH demo program — Rule 30
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function rule30(n){var row=[1];for(var g=0;g<n;g++){var next=[];for(var i=0;i<row.length+2;i++){var l=row[i-1]||0,c=row[i]||0,r=row[i+1]||0;next.push(l^(c||r));}row=next;}return row;}
var r5=rule30(5);
check("grows each generation", r5.length, 11);
check("deterministic", rule30(5).join('')===r5.join(''), true);
check("starts with single 1", rule30(0).join(''), "1");
